const caps=['payroll-accruals.view','payroll-accruals.edit','payroll-preparations.view','work-pay.view','pay-periods.view','accounts.view','journals.view','journals.edit',...sessionEvidenceCapabilities,'session-evidence.view'];
async function fixture(throughSchema?:number){const f=await workFixture({throughSchema});try{
 for(const role of [f.staffRole,f.managerRole])for(const cap of [...caps,'financial-reports.view','session-time.record'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,role,cap]);
 const session=(await f.request('classes/'+f.c.id+'/sessions')).body.data[0];assert.equal((await f.request('sessions/'+session.id+'/change',{expectedVersion:1,reason:'Synthetic historical class',change:{kind:'reschedule',start:'2026-01-05T10:00',end:'2026-01-05T11:00'}})).response.status,200);
 const hourly=f.components.find(c=>c.code==='TEACH')!,engagement=(await f.create({components:[hourly]})).body.data;
 const timeInput={expectedVersion:0,assignmentId:f.assignment.id,assignmentVersion:1,sessionVersion:2,startsAt:'2026-01-05T15:00:00Z',endsAt:'2026-01-05T16:02:00Z',reason:'PRIVATE actual hourly work'},save=(patch:Record<string,unknown>={})=>f.request('sessions/'+session.id+'/my-time',{...timeInput,expectedVersion:1,...patch},'staff');assert.equal((await f.request('sessions/'+session.id+'/my-time',timeInput,'staff')).response.status,201);
 const expense=await f.made('finance/accounts',{code:'HOURLY-EXPENSE',name:'Synthetic hourly compensation',kind:'expense',operationalRole:'expense',hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic expense mapping'}),liability=await f.made('finance/accounts',{code:'HOURLY-PAYABLE',name:'Synthetic gross hourly payable',kind:'liability',operationalRole:'payable',hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic payable mapping'});
 const input={personId:f.actors.staff.person,from:'2026-01-05',through:'2026-01-05',timeZone:'America/Toronto',currencyId:f.currency.id,basis:'actual',reference:'HOURLY-JAN-1',postedOn:'2026-11-07',dueOn:'2026-12-07',period:{id:f.period.id,version:1},expenseAccount:{id:expense.id,version:1},liabilityAccount:{id:liability.id,version:1},earningReview:'PRIVATE gross liability review independent of operational evidence',taxReview:'PRIVATE gross base only, not net pay',roundingReview:'PRIVATE actual recorded time selected',reason:'PRIVATE requested hourly accrual'},accrue=(patch:Record<string,unknown>={},as='master',key?:string)=>f.request('payroll/hourly-accruals',{...input,...patch},as,{key}),cancel=(id:string,patch:Record<string,unknown>={},as='master',key?:string)=>f.request('payroll/hourly-accruals/'+id+'/void',{period:input.period,postedOn:'2026-11-08',reason:'PRIVATE reviewed retained correction',...patch},as,{key});
 return {...f,session,engagement,hourly,timeInput,save,expense,liability,hourlyInput:input,accrue,cancel};
}catch(e){await f.pg.close();throw e;}}
type Fixture=Awaited<ReturnType<typeof fixture>>;
function check(name:string,run:(f:Fixture)=>Promise<void>,nativeOnly=false){test(name,{skip:nativeOnly&&!process.env.TEST_DATABASE_URL},async()=>{const f=await fixture();try{await run(f);}finally{await f.pg.close();}});}
async function made(f:Fixture,patch:Record<string,unknown>={}){const r=await f.accrue(patch);assert.equal(r.response.status,201,JSON.stringify({body:r.body,failures:f.metrics.queryFailures}));return r.body.data;}
async function secondClass(f:Fixture,options:{hubId?:string;rate?:string;startsAt?:string;endsAt?:string}={}){const c=await f.made('classes',{hubId:options.hubId??f.hub,courseId:f.c.course_id,courseVersion:1,name:'Synthetic concurrent payroll class',mode:'in_person',schedule:{oneOff:[{start:'2026-01-05T10:00',end:'2026-01-05T12:00'}]}}),a=await f.made('classes/'+c.id+'/staff',{personId:f.actors.staff.person,role:'teacher',startsOn:'2026-01-01',reason:'Synthetic additional teaching'}),s=(await f.request('classes/'+c.id+'/sessions')).body.data[0],e=await f.create({code:'SECOND',hubId:options.hubId??f.hub,components:[{...f.hourly,assignment:{id:a.id,version:1},amount:options.rate??'30'}]});assert.equal(e.response.status,201,JSON.stringify(e.body));const saved=await f.request('sessions/'+s.id+'/my-time',{...f.timeInput,expectedVersion:0,assignmentId:a.id,assignmentVersion:1,sessionVersion:1,startsAt:options.startsAt??'2026-01-05T15:30:00Z',endsAt:options.endsAt??'2026-01-05T16:30:00Z'},'staff');assert.equal(saved.response.status,201,JSON.stringify(saved.body));return {c,a,s,engagement:e.body.data};}
async function nativeInsert(f:Fixture,p:any,patch:Record<string,unknown>={}){const i=p.payload,s=p.review_context.source,plan=p.review_context.plan,fields={academy_id:f.a,id:p.target_id,person_id:i.personId,reference:i.reference,from_on:i.from,through_on:i.through,time_zone:i.timeZone,basis:i.basis,currency_id:i.currencyId,currency_version:1,unit_scale:2,amount_minor:plan.gross.minor,posted_on:i.postedOn,due_on:i.dueOn,period_id:i.period.id,period_version:i.period.version,expense_account:i.expenseAccount.id,expense_version:i.expenseAccount.version,liability_account:i.liabilityAccount.id,liability_version:i.liabilityAccount.version,input:JSON.stringify(i),source_snapshot:JSON.stringify(s),earning_plan:JSON.stringify(plan),approval_id:p.id,created_by:f.actors.master.person,...patch},rows=Object.entries(fields);await f.pg.query('INSERT INTO public.payroll_hourly_accruals('+rows.map(([k])=>k).join(',')+') VALUES('+rows.map(([k],n)=>'$'+(n+1)+(['input','source_snapshot','earning_plan'].includes(k)?'::jsonb':'')).join(',')+')',rows.map(([,v])=>v));}
async function nativeSources(f:Fixture,p:any){await f.pg.query("INSERT INTO public.payroll_hourly_entry_sources(academy_id,accrual_id,entry_id,entry_version,person_id,pricing_fingerprint) SELECT $1,$2,(x->>'entryId')::uuid,(x->>'entryVersion')::integer,$3,x->>'pricingFingerprint' FROM jsonb_array_elements($4::jsonb) x",[f.a,p.target_id,f.actors.staff.person,JSON.stringify(p.review_context.plan.sourceIdentities)]);}
async function nativeClaims(f:Fixture,p:any){await f.pg.query("INSERT INTO public.payroll_hourly_claims(academy_id,accrual_id,ordinal,person_id,start_ms,end_ms) SELECT $1,$2,v.ordinality::integer,$3,(v.value->>'start')::bigint,(v.value->>'end')::bigint FROM jsonb_array_elements($4::jsonb) WITH ORDINALITY v(value,ordinality)",[f.a,p.target_id,f.actors.staff.person,JSON.stringify(p.review_context.plan.timeClaims)]);}
async function saveNativeCase(f:Fixture,p:any){await f.pg.query('INSERT INTO public.approval_requests(academy_id,id,requester_id,requester_kind,credential_snapshot,grants_hash,action,target_id,target_version,payload,scope,dependency_hash,review_context,privacy_capability) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7,$8,0,$9::jsonb,$10::jsonb,$11,$12::jsonb,$13)',[f.a,p.id,p.requester_id,p.requester_kind,JSON.stringify(p.credential_snapshot),p.grants_hash,p.action,p.target_id,JSON.stringify(p.payload),JSON.stringify(p.scope),p.dependency_hash,JSON.stringify(p.review_context),p.privacy_capability]);}
async function nativeCase(f:Fixture,original:any,postedOn:string,releaseFloorOn?:string|null){const p={...structuredClone(original),id:randomUUID(),target_id:randomUUID()};p.payload.postedOn=postedOn;if(releaseFloorOn===undefined)delete p.review_context.plan.releaseFloorOn;else p.review_context.plan.releaseFloorOn=releaseFloorOn;await saveNativeCase(f,p);return p;}
async function nativeJournal(f:Fixture,p:any){await f.pg.query("INSERT INTO public.finance_journals(academy_id,id,period_id,period_version,posted_on,description,reference,line_count,posted_by,approval_id,purpose) VALUES($1,$2,$3,1,$6::date,'Recorded hourly gross accrual','PAYROLL-HOURLY',2,$4,$5,'activity')",[f.a,p.target_id,f.period.id,f.actors.master.person,p.id,p.payload.postedOn]);await f.pg.query("INSERT INTO public.finance_journal_lines(academy_id,journal_id,line_number,account_id,account_version,side,amount_minor,note) VALUES($1,$2,1,$3,1,'debit',2067,''),($1,$2,2,$4,1,'credit',2067,'')",[f.a,p.target_id,f.expense.id,f.liability.id]);}

check('hourly accrual posts exact gross liability and durable worker claims without turning missing session evidence into unpaid work',async f=>{
 const d=await made(f);assert.equal(d.grossBaseAmount,'20.67');assert.equal(d.claimsPersisted,true);assert.equal(d.accountingPosted,true);assert.equal(d.operationalReviewRequired,true);assert.equal(d.timeReviewRequired,true);assert.equal(d.payoutReady,false);assert.equal(d.cashMovementPerformed,false);assert.equal(d.statutoryDeductionsCalculated,false);
 assert.deepEqual((await f.pg.query('SELECT side,amount_minor::text,note FROM public.finance_journal_lines WHERE journal_id=$1 ORDER BY line_number',[d.id])).rows,[{side:'debit',amount_minor:'2067',note:''},{side:'credit',amount_minor:'2067',note:''}]);assert.equal((await f.pg.query('SELECT * FROM public.payroll_hourly_claims WHERE accrual_id=$1 AND release_id IS NULL',[d.id])).rows.length,1);assert.equal((await f.pg.query('SELECT * FROM public.finance_journal_lines WHERE account_id=$1',[f.cash.id])).rows.length,0);
 assert.equal((await f.request('reports/finance/profit-loss?from=2026-01-01&through=2026-12-31')).body.data.currencies[0].expenses.amount,'20.67');assert.equal((await f.request('payroll/hourly-accruals')).body.data[0].id,d.id);assert.doesNotMatch(JSON.stringify(d),/PRIVATE|source_snapshot|earningReview|taxReview|sourceAllocations|expenseAccount/);
 assert.equal((await f.accrue({reference:'DIFFERENT-REF'})).response.status,409);assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,1);
});
check('configured rounding records the selected amount but reserves actual work that rounds down',async f=>{const d=await made(f,{basis:'configured'});assert.equal(d.grossBaseAmount,'20.00');assert.equal(d.configuredReductionRequiresReview,true);const c=(await f.pg.query<{start_ms:string;end_ms:string}>('SELECT start_ms::text,end_ms::text FROM public.payroll_hourly_claims')).rows[0];assert.equal(BigInt(c.end_ms)-BigInt(c.start_ms),3720000n);assert.equal((await f.accrue({reference:'RETRY-ACTUAL'})).response.status,409);});
check('attendance changes stale pending hourly reviews and cannot double-accrue a previously priced time source',async f=>{
 const head={...f.components.find(c=>c.code==='HEAD')!,headcountBasis:'present',minimumStudents:0,includedStudents:0};assert.equal((await f.amend(f.engagement.id,{components:[head]})).response.status,200);
 assert.equal((await f.request('enrollments/'+f.e.id+'/change',{expectedVersion:1,joinsOn:'2026-01-01',reason:'Historical observed membership'})).response.status,200);
 const sheet=(expectedVersion:number,status:string)=>f.request('sessions/'+f.session.id+'/attendance/change',{expectedVersion,sessionVersion:2,entries:[{enrollmentId:f.e.id,enrollmentVersion:2,status,note:'PRIVATE attendance'}],reason:'Attendance source revision'});
 assert.equal((await sheet(0,'present')).response.status,200);const pending=await f.accrue({},'manager');assert.equal(pending.response.status,202,JSON.stringify(pending.body));
 assert.equal((await sheet(1,'absent')).response.status,200);const stale=await f.approve(pending.body.approval.id);assert.equal(stale.response.status,409,JSON.stringify(stale.body));assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,0);
 const d=await made(f);assert.equal(d.grossBaseAmount,'25.83');assert.equal((await sheet(2,'late')).response.status,200);const retry=await f.accrue({reference:'OTHER-REFERENCE'});assert.equal(retry.response.status,409);assert.equal(retry.body.error.code,'HOURLY_SOURCE_CORRECTION_REQUIRED');assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,1);
 assert.equal((await f.cancel(d.id)).response.status,201);const corrected=await made(f,{reference:'REVIEWED-REPLACEMENT',postedOn:'2026-11-08'});assert.equal(corrected.grossBaseAmount,'28.42');assert.equal((await f.pg.query('SELECT sum(CASE WHEN side=\'debit\' THEN amount_minor ELSE -amount_minor END)::text n FROM public.finance_journal_lines WHERE account_id=$1',[f.expense.id])).rows[0].n,'2842');
});
check('replacement booking cannot precede its retained reversal and dated financial reports never acquire a duplicate liability',async f=>{
 const first=await made(f);assert.equal((await f.cancel(first.id)).response.status,201);const approvals=(await f.pg.query('SELECT id FROM public.approval_requests')).rows.length,rejected=await f.accrue({reference:'REPLACEMENT'});assert.equal(rejected.response.status,409);assert.equal(rejected.body.error.code,'HOURLY_CORRECTION_DATE_REQUIRED');assert.equal((await f.pg.query('SELECT id FROM public.approval_requests')).rows.length,approvals);assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,2);
 const d=await made(f,{reference:'REPLACEMENT',postedOn:'2026-11-08'});assert.equal(d.grossBaseAmount,'20.67');const plan=(await f.pg.query<{earning_plan:{releaseFloorOn:string}}>('SELECT earning_plan FROM public.payroll_hourly_accruals WHERE id=$1',[d.id])).rows[0].earning_plan;assert.equal(plan.releaseFloorOn,'2026-11-08');
 for(const through of ['2026-11-07','2026-11-08']){const profit=await f.request('reports/finance/profit-loss?from=2026-11-07&through='+through),sheet=await f.request('reports/finance/balance-sheet?through='+through);assert.equal(profit.response.status,200);assert.equal(profit.body.data.currencies[0].expenses.amount,'20.67');assert.equal(sheet.response.status,200);assert.equal(sheet.body.data.currencies[0].liabilities.amount,'20.67');assert.equal(sheet.body.data.currencies[0].balanced,true);}
});
check('moved source identities require the reversal date even when replacement hours no longer intersect released time',async f=>{
 const first=await made(f);assert.equal((await f.save({startsAt:'2026-01-05T17:00:00Z',endsAt:'2026-01-05T18:00:00Z'})).response.status,200);assert.equal((await f.cancel(first.id)).response.status,201);const early=await f.accrue({reference:'MOVED-DATED'});assert.equal(early.response.status,409);assert.equal(early.body.error.code,'HOURLY_CORRECTION_DATE_REQUIRED');assert.equal((await made(f,{reference:'MOVED-DATED',postedOn:'2026-11-08'})).grossBaseAmount,'20.00');
});
check('a later correction in one half-open day does not block an independently unclaimed adjacent day with the same identity',async f=>{
 assert.equal((await f.save({startsAt:'2026-01-05T23:30:00Z',endsAt:'2026-01-06T00:30:00Z'})).response.status,200);const first=await made(f,{timeZone:'UTC'}),next=await f.accrue({timeZone:'UTC',from:'2026-01-06',through:'2026-01-06',reference:'PENDING-NEXT-DAY'},'staff');assert.equal(next.response.status,202);assert.equal((await f.cancel(first.id,{postedOn:'2026-11-20'})).response.status,201);const approved=await f.approve(next.body.approval.id,'manager');assert.equal(approved.response.status,200,JSON.stringify(approved.body));assert.equal(approved.body.data.postedOn,'2026-11-07');assert.equal(approved.body.data.grossBaseAmount,'10.00');
});
check('successive corrections use the latest relevant release',async f=>{
 const first=await made(f);assert.equal((await f.cancel(first.id)).response.status,201);const second=await made(f,{reference:'SECOND',postedOn:'2026-11-08'});assert.equal((await f.cancel(second.id,{postedOn:'2026-11-10'})).response.status,201);assert.equal((await f.accrue({reference:'THIRD',postedOn:'2026-11-09'})).body.error.code,'HOURLY_CORRECTION_DATE_REQUIRED');assert.equal((await made(f,{reference:'THIRD',postedOn:'2026-11-10'})).grossBaseAmount,'20.67');
});
check('native release-date and reviewed-floor guards reject otherwise balanced complete postings independently of HTTP',async f=>{
 const first=await made(f);assert.equal((await f.cancel(first.id)).response.status,201);const pending=await f.accrue({reference:'NATIVE-DATED',postedOn:'2026-11-08'},'staff');assert.equal(pending.response.status,202);const original=(await f.pg.query<any>('SELECT * FROM public.approval_requests WHERE id=$1',[pending.body.approval.id])).rows[0];
 for(const [on,floor,pattern] of [['2026-11-07','2026-11-08',/HOURLY_CORRECTION_DATE_REQUIRED/],['2026-11-08','2026-11-07',/HOURLY_RELEASE_DATE_REVIEW_REQUIRED/]] as const){await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.exec('SET LOCAL ROLE kavosh_runtime');const p=await nativeCase(f,original,on,floor);await nativeInsert(f,p);await nativeJournal(f,p);await nativeClaims(f,p);await nativeSources(f,p);await f.pg.query("UPDATE public.approval_requests SET status='applied',version=2,reviewer_id=$2,decided_at=now() WHERE id=$1",[p.id,f.actors.master.person]);await assert.rejects(f.pg.exec('COMMIT'),pattern);}finally{await f.pg.exec('ROLLBACK');}}
 assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,2);assert.equal((await f.pg.query('SELECT * FROM public.payroll_hourly_claims WHERE release_id IS NULL')).rows.length,0);assert.equal((await f.approve(pending.body.approval.id)).response.status,200);
});
